"""Console A/B halves preserve every beat, navigation, follow and full player pages."""
import argparse,json
from pathlib import Path
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);out=p.parse_args().output.resolve();out.mkdir(parents=True,exist_ok=False);root=Path(__file__).resolve().parents[1]
with sync_playwright() as pw:
 b=pw.chromium.launch(channel='msedge',headless=True);page=b.new_page(viewport={'width':1366,'height':768});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto((root/'SkyMusicStudio_Standalone.html').as_uri());page.locator('.card-play').first.click();score=page.evaluate('JSON.stringify(window.__SKY_STUDIO_TEST__.state.project.score)');page.locator('#scoreEditorBtn').click();page.locator('#consoleGenerateTab').click();assert page.locator('#pageLabel').inner_text()=='1A / 41'
 def ids():return page.locator('#beatGrid .beat[data-index]').evaluate_all('es=>es.map(e=>Number(e.dataset.index))')
 assert ids()==list(range(16));assert page.locator('#beatGrid .beat').count()==16;assert len(page.locator('#beatGrid').evaluate('e=>getComputedStyle(e).gridTemplateRows').split())==2
 assert page.locator('#beatGrid .beat').last.bounding_box()['y']+page.locator('#beatGrid .beat').last.bounding_box()['height']<=page.locator('#consoleGridSlot .grid-pane').bounding_box()['y']+page.locator('#consoleGridSlot .grid-pane').bounding_box()['height'];page.screenshot(path=str(out/'1A.png'));page.locator('#pageNext').click();assert page.locator('#pageLabel').inner_text()=='1B / 41';assert ids()==list(range(16,32));page.screenshot(path=str(out/'1B.png'));page.locator('#pageNext').click();assert page.locator('#pageLabel').inner_text()=='2A / 41';assert ids()==list(range(32,48));page.locator('#pagePrev').click();assert page.locator('#pageLabel').inner_text()=='1B / 41';page.locator('#pagePrev').click();assert page.locator('#pageLabel').inner_text()=='1A / 41'
 page.locator('#seekSlider').evaluate("e=>{e.value=2600;e.dispatchEvent(new Event('input'))}");page.locator('#consolePlay').click();page.wait_for_function('window.__SKY_STUDIO_TEST__.state.isPlaying');page.wait_for_function('document.getElementById("pageLabel").textContent.startsWith("1B")');page.locator('#consolePlay').click();assert int(page.locator('#beatGrid .beat.active').get_attribute('data-index'))>=16
 page.locator('#seekSlider').evaluate("e=>{e.value=e.max;e.dispatchEvent(new Event('input'))}");assert page.locator('#pageLabel').inner_text()=='41A / 41';assert page.locator('#beatGrid .beat').count()==16;assert page.locator('#pageNext').is_disabled()
 page.locator('#consoleClose').click();page.locator('#discardChanges').click();assert page.locator('#beatGrid .beat').count()==32;assert page.locator('#pageLabel').inner_text()=='41 / 41';assert page.evaluate('JSON.stringify(window.__SKY_STUDIO_TEST__.state.project.score)')==score
 page.locator('#scoreEditorBtn').click();assert page.locator('#pageLabel').inner_text()=='41A / 41'
 page.set_viewport_size({'width':390,'height':844});page.locator('#seekSlider').evaluate("e=>{e.value=0;e.dispatchEvent(new Event('input'))}");page.wait_for_timeout(80);page.screenshot(path=str(out/'mobile.png'));assert page.locator('#beatGrid .beat').count()==16;assert not errors,errors;b.close()
(out/'results.json').write_text(json.dumps({'passed':True,'halves':'0–15 / 16–31','sequence':['1A','1B','2A'],'follow':True,'lastHalf':True,'restore32':True,'scoreUnchanged':True,'errors':errors},indent=2),'utf-8');print('PASS 16-cell A/B pages, sequential navigation, automatic following, final half, mobile and full-page restoration')
